configuration.tbelDecoder:
// 1. Gestione robusta del payload (stringa o oggetto già parsato)
var data = {};
if (typeof payload === 'string') {
    try {
        data = JSON.parse(payload);
    } catch (e) {
        data = decodeToJson(payload) || {};
    }
} else if (typeof payload === 'object') {
    data = payload;
}

// 2. Estrazione del livello dati (gestisce sia JSON annidato che diretto)
var p = data.payload ? data.payload : data;

// 3. Estrazione sicura dei sotto-oggetti hw e analysis
var hw = p.hw || {};
var analysis = p.analysis || {};

// 4. Mappatura solida e pulita delle sole metriche primitive
var cleanTelemetry = {
    spore_count: Number(analysis.spore_count || 0),
    detected: analysis.detected ? 1 : 0,
    frame_id: Number(p.frame_id || 0),
    sample_id: String(p.sample_id || ""),
    
    // Diagnostica Hardware
    cpu_temp_c: Number(hw.cpu_temp_c || 0),
    processing_time_s: Number(hw.processing_time_s || 0),
    ram_used_percent: (hw.ram && hw.ram.used_percent !== undefined) ? Number(hw.ram.used_percent) : 0,
    disk_used_percent: (hw.disk && hw.disk.used_percent !== undefined) ? Number(hw.disk.used_percent) : 0
};

// 5. Ritorno della struttura per ThingsBoard
return {
   deviceName: String(p.device_id || "sensore_001"),
   deviceType: "Optical Biosensor",
   telemetry: cleanTelemetry
};
